const result = await Bun.build({
  entrypoints: ['./sessionStores.ts'],
  target: 'bun',
  metafile: true,
  outdir: '/tmp/claude-0/-home-user-thyrox--thyrox-pool-worktrees-d4ab92b4efb0-5/72bc0773-df72-4649-b315-7c8956252f68/scratchpad/out2',
})
if (!result.metafile) { console.log('no metafile'); process.exit(1) }
const inputs = result.metafile.inputs
// find shortest path from entry to a repl file via BFS over imports graph
const entry = Object.keys(inputs).find(p => p.endsWith('sessionStores.ts'))!
const target = Object.keys(inputs).find(p => p.includes('/packages/repl/src/onChangeAppState.ts'))!
console.log('entry', entry)
console.log('target', target)
const visited = new Set<string>([entry])
const parent = new Map<string, string>()
const queue = [entry]
while (queue.length) {
  const cur = queue.shift()!
  if (cur === target) break
  const info = inputs[cur]
  if (!info) continue
  for (const imp of info.imports) {
    if (!visited.has(imp.path)) {
      visited.add(imp.path)
      parent.set(imp.path, cur)
      queue.push(imp.path)
    }
  }
}
// reconstruct path
let path = [target]
let cur = target
while (parent.has(cur)) {
  cur = parent.get(cur)!
  path.push(cur)
}
console.log(path.reverse().join('\n  -> '))
EOF
