cat > /home/user/thyrox/.thyrox/pool-worktrees/d4ab92b4efb0/5/src/packages/agent/__tests__/sessionStoresImports.test.ts <<'EOF'
/**
 * `sessionStores.ts` nombraba `@thyrox/repl/onChangeAppState.js` con un
 * `require()` — perezoso en ejecución, pero el grafo estático que arrastra
 * (~151 módulos de `repl`, medido con `Bun.build({metafile:true})` sobre
 * este mismo archivo como único entrypoint) igual entra al bundle del
 * bootstrap: el especificador literal se resuelve exista o no la llamada.
 * Cortar la dependencia (el parámetro `onChange` la invierte: quien crea el
 * store decide qué escucha, no `sessionStores.ts`) saca ese grafo entero.
 *
 * Excepción declarada y medida aparte: `effort.ts` (import directo,
 * preexistente, fuera del alcance de este corte) llega a
 * `repl/diagnostics/debugFilter.ts` vía
 * `provider/authAlias.ts` → `local-observability/debug.ts`. Es la única ruta
 * que sigue entrando y no depende de `onChangeAppState`.
 */
import { describe, expect, test } from 'bun:test'
import { join } from 'node:path'

const ENTRY = join(import.meta.dir, '..', 'sessionStores.ts')
const KNOWN_UNRELATED_LEAK = '/packages/repl/src/diagnostics/debugFilter.ts'

describe('sessionStores.ts no arrastra el paquete repl', () => {
  test('el grafo estático (Bun.build metafile) no referencia repl/onChangeAppState', async () => {
    const result = await Bun.build({
      entrypoints: [ENTRY],
      target: 'bun',
      metafile: true,
    })
    expect(result.success).toBe(true)
    expect(result.metafile).toBeDefined()
    const inputs = Object.keys(result.metafile!.inputs)
    const replInputs = inputs.filter(p => p.includes('/packages/repl/'))
    const unexpected = replInputs.filter(p => !p.endsWith(KNOWN_UNRELATED_LEAK))
    expect(unexpected).toEqual([])
  })

  test('importar el módulo no ejecuta ningún archivo de repl (require.cache)', async () => {
    await import(ENTRY)
    const loaded = Object.keys(require.cache)
    const repl = loaded.filter(p => p.includes('/packages/repl/'))
    const unexpected = repl.filter(p => !p.endsWith(KNOWN_UNRELATED_LEAK))
    expect(unexpected).toEqual([])
  })
})
EOF
